import{_ as a,o as r,c as e,a5 as n}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"855-批量检测损坏图片并移动到指定文件夹-保持源结构","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["保持目录结构","图片校验","批量检测","损坏图片搬移"]},"headers":[{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}],"relativePath":"md/图片批处理/855-批量检测损坏图片并移动到指定文件夹-保持源结构.md","filePath":"md/图片批处理/855-批量检测损坏图片并移动到指定文件夹-保持源结构.md"}'),o={name:"md/图片批处理/855-批量检测损坏图片并移动到指定文件夹-保持源结构.md"};function l(s,t,p,i,h,_){return r(),e("div",null,[...t[0]||(t[0]=[n('<p>用于批量检查图片文件是否损坏并把有问题的图片按原有层级移动到指定文件夹的小工具。</p><p>界面全是按钮和输入框，选择源文件夹和目标文件夹就能一键检测，无需手动逐个验证图片是否能打开。</p><p>处理过程会记录日志，方便查看哪些文件正常、哪些被移动。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208222627176520398780822.png" alt=""></p><p>【1】、支持的文件格式：JPG、JPEG、PNG、GIF、BMP、TIFF、TIF、WEBP、HEIC</p><p>【2】、是否支持子文件夹穿透：支持</p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208222706176520402669062.png" alt=""></p><p>**点击就能用：**源路径、目标路径支持浏览选择，开始、停止、清空输入、清空日志都是按钮操作。<br> **格式覆盖面广：**支持 JPG、JPEG、PNG、GIF、BMP、TIFF、TIF、WEBP、HEIC 常见图片格式，按规则检查文件头尾并用 Pillow 验证是否可读。<br> **保留目录结构：**把检测出的损坏图片移动到目标目录时，会按原始相对路径创建子目录，保证层级一致。<br> **实时日志：**检测、移动、正常结果都会写入日志框，结束后总结损坏文件清单。</p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><p>**第一步：**在主界面点击“选择文件夹”按钮，挑选源图片所在的总目录；再点击目标路径的“选择文件夹”，指定损坏文件要搬到的目录。<br> **第二步：**确认路径无误后点击“开始程序”，工具会逐个检测源目录及其子目录中的图片。<br> **第三步：**若需要中途停下，点击“结束任务”。检测完成后，损坏图片会按原结构搬到目标目录，日志区会显示已移动的文件列表。<br> **第四步：**如需重新开始，可点击“清空输入框”和“清空日志”整理界面，再设置新的路径继续使用。</p><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><p>**场景一：**整理旅行照片时发现有些文件打不开，选择照片总目录作为源，指定一个空文件夹作为目标，点击开始。</p><p>检测结束后，损坏的照片会被集中搬到目标目录，源目录只留下正常文件。</p><p>**场景二：**批量收集的网络素材里混杂坏图，运行工具扫描素材目录，把坏图分离出去，方便后续只处理健康素材。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q：为什么有些图片判定损坏？</strong><br> A：文件头尾不符合格式、内容被截断或 无法识别都会被判为损坏。<br><strong>Q：日志里显示路径太长看不清？</strong><br> A：可以复制日志内容到记事本查看，或使用更短的文件夹路径再试。<br><strong>Q：停止任务后还能继续吗？</strong><br> A：可以，停止后重新点击开始即可，会从头重新检测当前源目录。<br><strong>Q：支持哪些格式？</strong><br> A：当前支持 JPG、JPEG、PNG、GIF、BMP、TIFF、TIF、WEBP、HEIC。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后双击使用即可，初始打开可能慢，耐心等待</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222222809177177048952015.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2246.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2246.html</a></p>',27)])])}const d=a(o,[["render",l]]);export{c as __pageData,d as default};
